import { useCallback, useId, useMemo, useState } from 'react';
import { Button } from '@jinx-ui/react';

type SignupValues = {
  name: string;
  email: string;
  phone: string;
  country: string;
  city: string;
  street: string;
  zip: string;
};

type SignupWizardProps = {
  onSubmit: (values: SignupValues) => void;
  initialValues?: Partial<SignupValues>;
};

const STEPS = ['Контакты', 'Адрес', 'Проверка'] as const;

const EMPTY_VALUES: SignupValues = {
  name: '',
  email: '',
  phone: '',
  country: '',
  city: '',
  street: '',
  zip: '',
};

const CONTACT_FIELDS: Array<{ key: keyof SignupValues; label: string; type: string }> = [
  { key: 'name', label: 'Имя', type: 'text' },
  { key: 'email', label: 'Email', type: 'email' },
  { key: 'phone', label: 'Телефон', type: 'tel' },
];

const ADDRESS_FIELDS: Array<{ key: keyof SignupValues; label: string; type: string }> = [
  { key: 'country', label: 'Страна', type: 'text' },
  { key: 'city', label: 'Город', type: 'text' },
  { key: 'street', label: 'Улица, дом', type: 'text' },
  { key: 'zip', label: 'Почтовый индекс', type: 'text' },
];

export default function SignupWizard({ onSubmit, initialValues }: SignupWizardProps) {
  const fieldId = useId();
  const [step, setStep] = useState(0);
  const [values, setValues] = useState<SignupValues>({ ...EMPTY_VALUES, ...initialValues });

  const isLastStep = step === STEPS.length - 1;

  const setField = useCallback((key: keyof SignupValues, value: string) => {
    setValues((current) => ({ ...current, [key]: value }));
  }, []);

  const summary = useMemo(
    () => [...CONTACT_FIELDS, ...ADDRESS_FIELDS].map((field) => ({
      label: field.label,
      value: values[field.key].trim(),
    })),
    [values],
  );

  const goBack = () => setStep((current) => Math.max(0, current - 1));

  const goNext = () => {
    if (isLastStep) {
      onSubmit(values);
      return;
    }
    setStep((current) => Math.min(STEPS.length - 1, current + 1));
  };

  const renderFields = (fields: typeof CONTACT_FIELDS) => (
    <div className="jx-stack" style={{ gap: 'var(--jx-space-4)' }}>
      {fields.map((field) => (
        <div className="jx-field" key={field.key}>
          <label className="jx-label" htmlFor={`${fieldId}-${field.key}`}>
            {field.label}
          </label>
          <input
            className="jx-input"
            id={`${fieldId}-${field.key}`}
            name={field.key}
            type={field.type}
            value={values[field.key]}
            onChange={(event) => setField(field.key, event.target.value)}
          />
        </div>
      ))}
    </div>
  );

  return (
    <form
      className="jx-card jx-stack"
      style={{ gap: 'var(--jx-space-6)', padding: 'var(--jx-space-6)' }}
      onSubmit={(event) => {
        event.preventDefault();
        goNext();
      }}
    >
      <ol
        className="jx-row"
        aria-label="Шаги регистрации"
        style={{ display: 'flex', gap: 'var(--jx-space-2)', listStyle: 'none', margin: 0, padding: 0 }}
      >
        {STEPS.map((title, index) => (
          <li
            key={title}
            className="jx-step"
            aria-current={index === step ? 'step' : undefined}
            data-state={index === step ? 'active' : index < step ? 'done' : 'idle'}
            style={{
              flex: 1,
              padding: 'var(--jx-space-2) var(--jx-space-3)',
              borderRadius: 'var(--jx-radius)',
              border: 'var(--jx-border-width) solid var(--jx-border)',
              color: index === step ? 'var(--jx-fg)' : 'var(--jx-fg-muted)',
              background: index === step ? 'var(--jx-surface-raised)' : 'var(--jx-surface)',
            }}
          >
            <span className="jx-text-sm">{`${index + 1}. ${title}`}</span>
          </li>
        ))}
      </ol>

      <section className="jx-stack" style={{ gap: 'var(--jx-space-4)' }} aria-live="polite">
        <h2 className="jx-heading" style={{ margin: 0 }}>
          {STEPS[step]}
        </h2>

        {step === 0 && renderFields(CONTACT_FIELDS)}
        {step === 1 && renderFields(ADDRESS_FIELDS)}
        {step === 2 && (
          <dl className="jx-stack" style={{ gap: 'var(--jx-space-2)', margin: 0 }}>
            {summary.map((item) => (
              <div
                key={item.label}
                style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-4)' }}
              >
                <dt className="jx-text-sm" style={{ color: 'var(--jx-fg-muted)' }}>
                  {item.label}
                </dt>
                <dd className="jx-text-sm" style={{ margin: 0, color: 'var(--jx-fg)' }}>
                  {item.value || '—'}
                </dd>
              </div>
            ))}
          </dl>
        )}
      </section>

      <footer style={{ display: 'flex', justifyContent: 'space-between', gap: 'var(--jx-space-3)' }}>
        <Button type="button" variant="ghost" onClick={goBack} disabled={step === 0}>
          Назад
        </Button>
        <Button type="submit" variant="primary">
          {isLastStep ? 'Отправить' : 'Дальше'}
        </Button>
      </footer>
    </form>
  );
}

